corrected_code:
app.get('/api/payments/history/:year', (req, res) => {
  const year = req.params.year;
  const userId = req.session.user_id;
  db.query(`SELECT * FROM payments WHERE YEAR(date) = ? AND user_id = ?`, [year, userId], (err, results) => {
    res.json(results);
  });
});
